import '../../src/styles/tokens.css';

const entry = new URL(location.href).searchParams.get('entry') ?? 'theme';
if (entry === 'foundation') await import('../../src/foundation.js');
else if (entry === 'button') await import('../../src/button.js');
else if (entry === 'input') await import('../../src/input.js');
else if (entry === 'card') await import('../../src/card.js');
else if (entry === 'checkbox') await import('../../src/checkbox.js');
else if (entry === 'radio') await import('../../src/radio.js');
else if (entry === 'switch') await import('../../src/switch.js');
else if (entry === 'select') await import('../../src/select.js');
else if (entry === 'icon') await import('../../src/icon.js');
else if (entry === 'icon-button') await import('../../src/icon-button.js');
else if (entry === 'tag') await import('../../src/tag.js');
else if (entry === 'status') await import('../../src/status.js');
else if (entry === 'page-layout') await import('../../src/page-layout.js');
else if (entry === 'section') await import('../../src/section.js');
else if (entry === 'breadcrumbs') await import('../../src/breadcrumbs.js');
else if (entry === 'tabs') await import('../../src/tabs.js');
else if (entry === 'segmented-control') await import('../../src/segmented-control.js');
else if (entry === 'sidebar') await import('../../src/sidebar.js');
else if (entry === 'topbar') await import('../../src/topbar.js');
else if (entry === 'app-shell') await import('../../src/app-shell.js');
else if (entry === 'tooltip') await import('../../src/tooltip.js');
else if (entry === 'dropdown') await import('../../src/dropdown.js');
else if (entry === 'dialog') await import('../../src/dialog.js');
else if (entry === 'drawer') await import('../../src/drawer.js');
else if (entry === 'toast') await import('../../src/toast.js');
else if (entry === 'validation-summary') await import('../../src/validation-summary.js');
else if (entry === 'combobox') await import('../../src/combobox.js');
else if (entry === 'command-palette') await import('../../src/command-palette.js');
else if (entry === 'pagination') await import('../../src/pagination.js');
else if (entry === 'table') await import('../../src/table.js');
else if (entry === 'avatar') await import('../../src/avatar.js');
else if (entry === 'empty-state') await import('../../src/empty-state.js');
else if (entry === 'skeleton') await import('../../src/skeleton.js');
else if (entry === 'progress') await import('../../src/progress.js');
else if (entry === 'kpi') await import('../../src/kpi.js');
else if (entry === 'chart') await import('../../src/chart.js');
else if (entry === 'full') await import('../../src/index.js');
else await import('../../src/theme.js');

if (entry === 'theme' || entry === 'full') await customElements.whenDefined('bm-theme');
(window as Window & { foundationReady?: boolean }).foundationReady = true;
